// RISC Architecture (e.g., ARM, RISC-V)
// Focus: Fixed length, simple instructions, pipelining.
// Register-to-Register operations required for ALU.

struct RISC_Instruction {
    uint8_t OpCode;     // E.g., ADD, SUB, LDR
    uint8_t Rd, Rs1, Rs2; // Dedicated Registers (R0-R31)
    uint16_t Immediate; // Fixed position, small immediate value
};

// Memory operations separate from compute
LOAD R1, [Address_X]    // Read from Memory
LOAD R2, [Address_Y]
ADD  R3, R1, R2         // Compute only in registers
STORE [Address_Z], R3   // Write result back

// CISC Architecture (e.g., x86)
// Focus: Variable length, complex instructions, microcode.
// Memory operands allowed directly in ALU operations.

// Instruction length highly variable (1 byte to 15 bytes)
// Defined by ModR/M and SIB bytes (complex addressing)

// Single instruction combining LOAD/ADD/STORE
ADD [EAX + EBX*4 + 0x10], 0x5   // Op: Mem += Constant
// Example: Add two complex memory locations (x86 often restricts Mem-to-Mem)
MOV EAX, [Addr_A]
ADD [Addr_C], EAX               // Loads and writes implicitly handled
